// m1CallElem: `o[k]()` on a heterogeneous object LITERAL (a typed record whose
// member is a function) has no static lowering: "dynamic keyed reads of '{ m:
// () => string; tag: string }'". Its own package, because a refused function
// poisons the whole module that holds it.
"use strict";
function t(f) { try { return String(f()); } catch (e) { return "THREW " + String(e && e.message); } }
function probe() { return "obj tag=" + (this && this.tag); }
var KM = "m";
function mkLit() { return { tag: "L", m: probe }; }
exports.m1CallElem = function () { var o = mkLit(); return t(function () { return o[KM](); }); };
